from __future__ import annotations

import ast
import dataclasses
import hashlib
import importlib
import inspect
import json
import re
import sys
from pathlib import Path
from typing import get_type_hints

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT / "backend"))
OUT = ROOT / "docs/audit/dashboard-2026-10-30"
REL = "backend/app/infrastructure/imports/passport_excel_importer.py"


def stable(value):
    if isinstance(value, frozenset):
        return {"type": "frozenset", "items": sorted(value)}
    if isinstance(value, re.Pattern):
        return {"type": "re.Pattern", "pattern": value.pattern, "flags": value.flags}
    if dataclasses.is_dataclass(value) and not isinstance(value, type):
        return {"type": type(value).__name__, "fields": dataclasses.asdict(value)}
    if isinstance(value, dict):
        return {key: stable(item) for key, item in value.items()}
    if isinstance(value, tuple):
        return {"type": "tuple", "items": [stable(item) for item in value]}
    return value


def snapshot() -> dict:
    module = importlib.import_module("app.infrastructure.imports.passport_excel_importer")
    source = json.loads((OUT / "passport-excel-architecture-original-source.json").read_text(encoding="utf-8"))["sources"][REL]["source"]
    original_class = next(node for node in ast.parse(source).body if isinstance(node, ast.ClassDef) and node.name == "PassportExcelImporter")
    methods = [node.name for node in original_class.body if isinstance(node, ast.FunctionDef)]
    constants = [node.target.id for node in ast.parse(source).body if isinstance(node, ast.AnnAssign) and isinstance(node.target, ast.Name)]
    importer = module.PassportExcelImporter
    row = module.ImportedPassportRow
    return {
        "public_importer_module_qualname": [importer.__module__, importer.__qualname__],
        "row_module_qualname": [row.__module__, row.__qualname__],
        "error_module_qualname": [module.PassportExcelImportError.__module__, module.PassportExcelImportError.__qualname__],
        "row_signature": str(inspect.signature(row)),
        "row_type_hints": {key: repr(value) for key, value in get_type_hints(row).items()},
        "row_fields": [{"name": field.name, "type": str(field.type), "init": field.init, "repr": field.repr, "compare": field.compare, "kw_only": field.kw_only, "default": field.default is dataclasses.MISSING, "default_factory": field.default_factory is dataclasses.MISSING, "metadata": dict(field.metadata)} for field in dataclasses.fields(row)],
        "row_dataclass_frozen": row.__dataclass_params__.frozen,
        "importer_signature": str(inspect.signature(importer)),
        "importer_type_hints": {key: repr(value) for key, value in get_type_hints(importer).items()},
        "methods": {name: {"signature": str(inspect.signature(getattr(importer, name))), "type_hints": {key: repr(value) for key, value in get_type_hints(getattr(importer, name)).items()}} for name in methods},
        "constant_values": {name: stable(getattr(module, name)) for name in constants},
        "class_catalog": importer.HEADER_ALIASES,
        "class_field_keys": sorted(importer.FIELD_KEYS),
    }


if __name__ == "__main__":
    mode = sys.argv[1]
    if mode == "before":
        paths = [REL, "backend/app/infrastructure/imports/passport_excel_formula.py", "backend/tests/unit/infrastructure/test_passport_excel_importer.py", "backend/tests/unit/infrastructure/test_passport_excel_formula_boundaries.py"]
        sources = {}
        for name in paths:
            raw = (ROOT / name).read_bytes()
            sources[name] = {"sha256": hashlib.sha256(raw).hexdigest(), "source": raw.decode("utf-8"), "lines": len(raw.decode("utf-8").splitlines())}
        (OUT / "passport-excel-architecture-original-source.json").write_text(json.dumps({"sources": sources}, indent=2) + "\n", encoding="utf-8")
    current = snapshot()
    path = OUT / f"passport-excel-architecture-{mode}-runtime.json"
    if mode == "after":
        assert json.loads(json.dumps(current)) == json.loads((OUT / "passport-excel-architecture-before-runtime.json").read_text(encoding="utf-8"))
    path.write_text(json.dumps(current, indent=2) + "\n", encoding="utf-8")
    print(json.dumps({"mode": mode, "methods": len(current["methods"]), "constants": len(current["constant_values"]), "dataclass_fields": len(current["row_fields"]), "all_runtime_contracts_equal": mode == "after"}))
